import { DrizzleQueryError } from 'drizzle-orm';
import fs from 'fs';
import { drizzle } from 'drizzle-orm/node-sqlite';
import path from 'path';

interface OpenDatabaseOptions {
  databasePath: string;
  schema: string;
  migrations?: readonly string[];
}

const INITIAL_SCHEMA_VERSION = 1;
const BUSY_TIMEOUT_MS = 5_000;

export class DatabaseSchemaMismatchError extends Error {
  constructor(
    readonly foundSchemaVersion: number,
    readonly expectedSchemaVersion: number,
  ) {
    super(
      `Database schema mismatch: found ${foundSchemaVersion}, expected ${expectedSchemaVersion}.`,
    );
    this.name = 'DatabaseSchemaMismatchError';
  }
}

export const closeDatabase = (db: ReturnType<typeof drizzle>): void => {
  db.$client.close();
};

export const openReadOnlyDatabase = ({
  databasePath,
  schemaVersion,
}: {
  databasePath: string;
  schemaVersion: number;
}): ReturnType<typeof drizzle> | null => {
  if (!fs.existsSync(databasePath)) return null;
  const { DatabaseSync } = process.getBuiltinModule(
    'node:sqlite',
  ) as typeof import('node:sqlite');
  const client = new DatabaseSync(databasePath, { readOnly: true });
  try {
    const version = Number(
      client.prepare('PRAGMA user_version').get()?.user_version,
    );
    if (version !== schemaVersion)
      throw new DatabaseSchemaMismatchError(version, schemaVersion);
    return drizzle({ client });
  } catch (error) {
    client.close();
    throw error;
  }
};

export const openDurableDatabaseSync = ({
  databasePath,
  schema,
  migrations = [],
}: OpenDatabaseOptions): ReturnType<typeof drizzle> => {
  const { DatabaseSync } = process.getBuiltinModule(
    'node:sqlite',
  ) as typeof import('node:sqlite');
  const supportedVersion = INITIAL_SCHEMA_VERSION + migrations.length;
  fs.mkdirSync(path.dirname(databasePath), { recursive: true, mode: 0o700 });
  const db = new DatabaseSync(databasePath);
  try {
    db.exec(`PRAGMA busy_timeout = ${BUSY_TIMEOUT_MS}`);
    const version = (): number =>
      Number(db.prepare('PRAGMA user_version').get()?.user_version);
    const assertSupported = (): void => {
      if (version() > supportedVersion)
        throw new Error(
          `Unsupported database schema ${version()} (supported: ${supportedVersion}); leaving ${databasePath} untouched`,
        );
    };
    assertSupported();
    if (version() < supportedVersion) {
      db.exec('BEGIN IMMEDIATE');
      try {
        assertSupported();
        if (version() === 0) {
          db.exec(schema);
          db.exec(`PRAGMA user_version = ${supportedVersion}`);
        } else {
          while (version() < supportedVersion) {
            const currentVersion = version();
            db.exec(migrations[currentVersion - INITIAL_SCHEMA_VERSION]);
            db.exec(`PRAGMA user_version = ${currentVersion + 1}`);
          }
        }
        db.exec('COMMIT');
      } catch (error) {
        db.exec('ROLLBACK');
        throw error;
      }
    }
    db.exec('PRAGMA foreign_keys = ON');
    db.exec('PRAGMA journal_mode = WAL');
    fs.chmodSync(databasePath, 0o600);
    return drizzle({ client: db });
  } catch (error) {
    db.close();
    throw error;
  }
};

export const openDurableDatabase = async (
  options: OpenDatabaseOptions,
): Promise<ReturnType<typeof drizzle>> => openDurableDatabaseSync(options);

export const transaction = <T>(
  db: ReturnType<typeof drizzle>,
  operation: () => T,
): T => {
  db.$client.exec('BEGIN IMMEDIATE');
  try {
    const value = operation();
    db.$client.exec('COMMIT');
    return value;
  } catch (error) {
    db.$client.exec('ROLLBACK');
    if (error instanceof DrizzleQueryError && error.cause !== undefined)
      throw error.cause;
    throw error;
  }
};
